WITH joined AS (SELECT src.*, d.stock_qty, d.category FROM order_items src JOIN products d ON src.product_id <=> d.id WHERE d.price < 1060), with_windows AS (SELECT *, MAX(unit_price) OVER w_running AS last7_max_unit_price, AVG(unit_price) OVER w_running AS last7_avg_unit_price, MIN(unit_price) OVER w_running AS last7_min_unit_price FROM joined WINDOW w_running AS (PARTITION BY order_id, product_id ORDER BY stock_qty, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), with_dims AS (SELECT src.*, p.product_name, p.price, p.launch_date FROM with_windows src LEFT JOIN products p ON src.product_id <=> p.id), cleaned AS (SELECT *, FLOOR(last7_avg_unit_price) AS last7_avg_unit_price_whole, COALESCE(category, 'NONE') AS resolved_category FROM with_dims WHERE product_id IS NOT NULL), deduped AS (SELECT id, product_id, quantity, category, last7_max_unit_price, product_name FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY unit_price DESC, id) AS row_num FROM cleaned) t WHERE row_num = 1), grouped AS (SELECT product_id, COUNT(*) FILTER (WHERE category = 'Fashion') AS fashion_rows, SUM(CASE WHEN category = 'Home' THEN last7_max_unit_price ELSE 0 END) AS home_last7_max_unit_price, PERCENTILE_APPROX(quantity, 0.95) AS quantity_p95 FROM deduped GROUP BY product_id) SELECT product_id, fashion_rows, quantity_p95 FROM grouped;
